-- Aprenda se Divertindo · 127 · Questões das leis novas (2024–2026)
-- Rode depois do 126-revisao-leis-2026.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.
-- Números 11547 a 11586 (40 questões): Lei 15.397/2026 (furto, roubo, receptação, estelionato), Lei 15.358/2026 (Antifacção),
-- Leis 15.380, 15.383, 15.384, 15.409, 15.410, 15.411, 15.412 e 15.438/2026 (Maria da Penha e violência contra a mulher),
-- Lei 15.353/2026 (estupro de vulnerável), Lei 15.487/2026 (ECA) e Lei 14.994/2024 (feminicídio e ameaça).
-- Entram nas trilhas Policial e Tribunais (Penal, Processo Penal e Legislação Extravagante).

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id": 11547, "materia": "pen", "nivel": 0, "enunciado": "Com a Lei 15.397/2026, a pena do furto simples passou a ser de:", "opcoes": ["Reclusão de 1 a 6 anos e multa", "Reclusão de 1 a 4 anos e multa", "Detenção de 6 meses a 2 anos", "Reclusão de 2 a 8 anos e multa"], "explicacao": "Art. 155, caput, do CP, com a redação da Lei 15.397/2026. Antes, a pena era de 1 a 4 anos."}, {"id": 11548, "materia": "pen", "nivel": 1, "enunciado": "Ana furtou uma bicicleta de madrugada, enquanto os donos dormiam. Desde a Lei 15.397/2026, a pena do furto, pelo repouso noturno:", "opcoes": ["Aumenta da metade", "Aumenta de 1/3", "Aumenta de 1/6", "Não sofre aumento"], "explicacao": "Art. 155, § 1º, do CP. A Lei 15.397/2026 elevou o aumento de 1/3 para metade."}, {"id": 11549, "materia": "pen", "nivel": 2, "enunciado": "Uma quadrilha furtou um carro em Salvador e o levou para ser vendido em Pernambuco. Após a Lei 15.397/2026, a pena desse furto é de:", "opcoes": ["Reclusão de 4 a 10 anos", "Reclusão de 3 a 8 anos", "Reclusão de 2 a 8 anos", "Reclusão de 1 a 6 anos"], "explicacao": "Art. 155, § 5º, do CP: veículo automotor transportado para outro estado ou para o exterior. A pena subiu de 3 a 8 para 4 a 10 anos."}, {"id": 11550, "materia": "pen", "nivel": 2, "enunciado": "O furto mediante fraude cometido por meio de dispositivo eletrônico ou informático (art. 155, § 4º-B, do CP) passou a ter, com a Lei 15.397/2026, pena de:", "opcoes": ["Reclusão de 4 a 10 anos e multa", "Reclusão de 4 a 8 anos e multa", "Reclusão de 2 a 8 anos e multa", "Reclusão de 1 a 6 anos e multa"], "explicacao": "A Lei 15.397/2026 elevou a pena do furto mediante fraude eletrônica para 4 a 10 anos."}, {"id": 11551, "materia": "pen", "nivel": 1, "enunciado": "Desde a Lei 15.397/2026, a pena do roubo simples (art. 157, caput, do CP) é de:", "opcoes": ["Reclusão de 6 a 10 anos e multa", "Reclusão de 4 a 10 anos e multa", "Reclusão de 5 a 12 anos e multa", "Reclusão de 8 a 15 anos e multa"], "explicacao": "A pena mínima do roubo subiu de 4 para 6 anos; a máxima continua em 10."}, {"id": 11552, "materia": "pen", "nivel": 2, "enunciado": "Após a Lei 15.397/2026, a pena da receptação simples (art. 180, caput, do CP) é de:", "opcoes": ["Reclusão de 2 a 6 anos e multa", "Reclusão de 1 a 4 anos e multa", "Detenção de 1 a 3 anos", "Reclusão de 3 a 8 anos e multa"], "explicacao": "A Lei 15.397/2026 elevou a pena da receptação dolosa simples de 1 a 4 para 2 a 6 anos."}, {"id": 11553, "materia": "pen", "nivel": 3, "enunciado": "Joana caiu em um golpe pelo WhatsApp e perdeu R$ 3 mil. Ela tem 35 anos e não quer processar o golpista. Pelo regime atual, a ação penal do estelionato:", "opcoes": ["É pública incondicionada, e o MP pode agir sem a vontade dela", "Depende de representação, por ela ter menos de 70 anos", "É privada, e só ela pode oferecer queixa", "Só existe se ela registrar o boletim de ocorrência em 6 meses"], "explicacao": "A Lei 15.397/2026 revogou o § 5º do art. 171, que exigia representação desde o Pacote Anticrime. O estelionato voltou a ser de ação pública incondicionada."}, {"id": 11554, "materia": "pen", "nivel": 4, "enunciado": "Sobre a revogação do § 5º do art. 171 do CP pela Lei 15.397/2026, é correto afirmar:", "opcoes": ["Como torna a lei penal mais grave, não alcança estelionatos cometidos antes da sua vigência", "Ela retroage e alcança os processos em andamento, mesmo nos casos em que a vítima não ofereceu representação no prazo", "Ela só vale para estelionatos contra pessoas maiores de 70 anos", "Ela transformou o estelionato em crime de ação penal privada"], "explicacao": "A regra da representação tem natureza mista (penal e processual), e a mudança que piora a situação do réu não retroage (art. 5º, XL, da CF)."}, {"id": 11555, "materia": "pen", "nivel": 1, "enunciado": "A pena da fraude eletrônica no estelionato (art. 171, § 2º-A, do CP) é de:", "opcoes": ["Reclusão de 4 a 8 anos e multa", "Reclusão de 1 a 5 anos e multa", "Reclusão de 2 a 6 anos e multa", "Detenção de 1 a 3 anos"], "explicacao": "A fraude eletrônica, criada pela Lei 14.155/2021, tem pena de 4 a 8 anos. O estelionato simples continua com 1 a 5 anos."}, {"id": 11556, "materia": "ppen", "nivel": 2, "enunciado": "Preso em flagrante por furto simples, Caio quer pagar fiança ainda na delegacia. Desde a Lei 15.397/2026:", "opcoes": ["O delegado não pode arbitrar a fiança, porque a pena máxima passou a ser de 6 anos", "O delegado pode arbitrar a fiança, porque o furto é crime sem violência ou grave ameaça à pessoa", "A fiança é proibida em qualquer furto", "O delegado pode conceder liberdade provisória sem fiança"], "explicacao": "Art. 322 do CPP: o delegado só arbitra fiança se a pena máxima não passar de 4 anos. Agora, quem decide é o juiz."}, {"id": 11557, "materia": "ppen", "nivel": 3, "enunciado": "Investigado primário confessou um furto simples, sem violência. Mesmo após a Lei 15.397/2026, ele ainda pode receber proposta de acordo de não persecução penal porque:", "opcoes": ["A pena mínima do furto simples continua inferior a 4 anos", "A pena máxima do furto simples continua inferior a 4 anos, mesmo após a mudança", "O acordo cabe em qualquer crime patrimonial", "O furto passou a ser crime de menor potencial ofensivo"], "explicacao": "Art. 28-A do CPP: exige pena mínima inferior a 4 anos. O furto simples tem mínimo de 1 ano."}, {"id": 11558, "materia": "pen", "nivel": 3, "enunciado": "Com a Lei 15.358/2026 (Lei Antifacção), o § 5º do art. 180 do CP, que previa o perdão judicial na receptação culposa e o privilégio na dolosa:", "opcoes": ["Foi revogado", "Foi ampliado para todos os crimes patrimoniais", "Passou a valer só para réus primários", "Foi transformado em causa de aumento de pena"], "explicacao": "A Lei 15.358/2026 revogou o § 5º do art. 180 do CP."}, {"id": 11559, "materia": "pen", "nivel": 4, "enunciado": "Pela Lei 15.358/2026, a receptação ligada a organização criminosa, milícia ou grupo paramilitar:", "opcoes": ["Tem a pena aumentada de 2/3 (art. 180, § 8º)", "Passou a ser crime hediondo em qualquer caso", "Tem a pena reduzida, se houver colaboração", "Deixou de ser crime autônomo, sendo absorvida pela organização criminosa"], "explicacao": "A Lei 15.358/2026 incluiu o § 8º no art. 180, com aumento de 2/3 nessas hipóteses."}, {"id": 11560, "materia": "ppen", "nivel": 2, "enunciado": "Com a Lei 15.358/2026, a audiência de custódia passou a ser feita, como regra, por:", "opcoes": ["Videoconferência", "Carta precatória", "Escrito, sem a presença do preso", "Decisão do delegado de polícia"], "explicacao": "A Lei Antifacção previu a audiência de custódia por videoconferência como regra, sem tirar do juiz o papel de presidi-la."}, {"id": 11561, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei Maria da Penha, com a mudança da Lei 15.380/2026, a audiência para a vítima se retratar da representação:", "opcoes": ["Só é marcada se a vítima manifestar expressamente o desejo de se retratar", "É marcada automaticamente pelo juiz em todos os processos, mesmo sem pedido da vítima", "Foi extinta", "Passou a ser feita na delegacia"], "explicacao": "Art. 16, parágrafo único, da Lei 11.340/2006, incluído pela Lei 15.380/2026."}, {"id": 11562, "materia": "leg", "nivel": 2, "enunciado": "Antes da Lei 15.380/2026, muitos juízes marcavam a audiência do art. 16 da Lei Maria da Penha mesmo sem pedido da vítima. A nova regra busca principalmente:", "opcoes": ["Evitar a revitimização e a pressão sobre a mulher para desistir", "Acelerar o arquivamento dos processos", "Permitir que o próprio agressor peça a audiência para confirmar se a vítima quer seguir com o processo", "Substituir a audiência por acordo entre as partes"], "explicacao": "A audiência agora só ocorre por manifestação expressa da vítima, o que evita que ela seja chamada a 'confirmar' a denúncia."}, {"id": 11563, "materia": "leg", "nivel": 3, "enunciado": "Na Lei Maria da Penha, a retratação da representação, nas ações condicionadas, deve ocorrer:", "opcoes": ["Perante o juiz, em audiência designada a pedido da vítima, antes do recebimento da denúncia, ouvido o MP", "Perante o delegado de polícia, por termo nos autos, até a conclusão do inquérito policial, independentemente de audiência", "Por escrito, a qualquer tempo antes da sentença", "Perante o promotor, sem audiência"], "explicacao": "Art. 16 da Lei 11.340/2006, com o parágrafo único da Lei 15.380/2026."}, {"id": 11564, "materia": "ppen", "nivel": 2, "enunciado": "Com a Lei 15.438/2026, nos crimes de violência doméstica e familiar contra a mulher de ação condicionada ou privada, o prazo para representação ou queixa passou a ser de:", "opcoes": ["12 meses", "6 meses", "30 dias", "2 anos"], "explicacao": "Art. 103, parágrafo único, do CP, art. 38, § 2º, do CPP e art. 16-A da Lei Maria da Penha, incluídos pela Lei 15.438/2026."}, {"id": 11565, "materia": "ppen", "nivel": 3, "enunciado": "Em março, Mariana descobriu que o ex-companheiro era o autor de mensagens com xingamentos enviadas a ela (injúria, crime de ação privada). Pela Lei 15.438/2026, nesse contexto de violência doméstica, o prazo para a queixa:", "opcoes": ["É de 12 meses, contados do dia em que ela soube quem é o autor", "É de 6 meses, contados da data do fato", "É de 12 meses, contados da data do fato", "Não existe, porque todo crime contra a mulher é de ação incondicionada"], "explicacao": "O termo inicial continua o mesmo (conhecimento da autoria); só o prazo dobrou, de 6 para 12 meses."}, {"id": 11566, "materia": "ppen", "nivel": 1, "enunciado": "Fora do contexto de violência doméstica contra a mulher, o prazo decadencial para representação ou queixa continua, em regra, de:", "opcoes": ["6 meses", "12 meses", "30 dias", "1 ano e meio"], "explicacao": "Art. 103 do CP e art. 38 do CPP. A Lei 15.438/2026 criou o prazo de 12 meses só para violência doméstica e familiar contra a mulher."}, {"id": 11567, "materia": "leg", "nivel": 0, "enunciado": "A Lei 15.384/2026 incluiu na Lei Maria da Penha a violência vicária, que é:", "opcoes": ["Atingir filhos, parentes ou dependentes da mulher para fazê-la sofrer ou controlá-la", "A violência praticada por vizinhos ou colegas de trabalho da vítima, fora do ambiente familiar e doméstico", "A violência entre irmãs", "A violência praticada pela internet"], "explicacao": "Art. 7º, VI, da Lei 11.340/2006, incluído pela Lei 15.384/2026."}, {"id": 11568, "materia": "pen", "nivel": 2, "enunciado": "O vicaricídio, criado pela Lei 15.384/2026 (art. 121-B do CP), consiste em:", "opcoes": ["Matar parente próximo ou dependente da mulher para causar sofrimento, punição ou controle sobre ela", "Matar a própria mulher por razões da condição do sexo feminino, no contexto de violência doméstica e familiar", "Induzir a mulher ao suicídio", "Matar o agressor em legítima defesa"], "explicacao": "É crime autônomo, distinto do feminicídio (art. 121-A)."}, {"id": 11569, "materia": "pen", "nivel": 3, "enunciado": "A pena do vicaricídio (art. 121-B do CP) é de:", "opcoes": ["Reclusão de 20 a 40 anos", "Reclusão de 12 a 30 anos", "Reclusão de 6 a 20 anos", "Reclusão de 24 a 30 anos"], "explicacao": "Mesma faixa do feminicídio (art. 121-A): 20 a 40 anos."}, {"id": 11570, "materia": "leg", "nivel": 3, "enunciado": "Sobre o vicaricídio, introduzido pela Lei 15.384/2026, é correto afirmar:", "opcoes": ["É crime hediondo e autônomo, não mera qualificadora do homicídio", "É qualificadora do homicídio, sem natureza hedionda, e se aplica só quando a mulher também é atingida", "É contravenção penal, punida com prisão simples", "Só se configura se a mulher também for morta"], "explicacao": "A lei incluiu o vicaricídio no art. 1º da Lei 8.072/1990 e o tipificou no art. 121-B do CP."}, {"id": 11571, "materia": "pen", "nivel": 4, "enunciado": "Para a configuração do vicaricídio, o elemento que o diferencia do homicídio comum é:", "opcoes": ["A finalidade de causar sofrimento, punição ou controle sobre a mulher", "O uso de arma de fogo", "O fato de a vítima ser menor de 14 anos ou maior de 60 anos, por ser mais vulnerável", "A premeditação"], "explicacao": "O dolo específico (finalidade de atingir a mulher) é o núcleo do art. 121-B."}, {"id": 11572, "materia": "leg", "nivel": 1, "enunciado": "Com a Lei 15.383/2026, a monitoração eletrônica do agressor na Lei Maria da Penha passou a ser:", "opcoes": ["Medida protetiva autônoma, que pode ser aplicada sozinha", "Proibida nos casos de violência psicológica e moral, por falta de previsão legal expressa", "Aplicada só depois da sentença condenatória", "Decidida pelo delegado, sem o juiz"], "explicacao": "Art. 22, § 5º, da Lei 11.340/2006. A vítima pode receber dispositivo que alerta a aproximação do agressor."}, {"id": 11573, "materia": "leg", "nivel": 2, "enunciado": "Pela Lei 15.411/2026, o afastamento imediato do agressor do lar (art. 12-C da Lei Maria da Penha) passou a ser possível também quando houver risco atual ou iminente à integridade:", "opcoes": ["Sexual, moral ou patrimonial da mulher", "Apenas física da mulher, como já previa a redação anterior", "Apenas dos filhos menores", "Do patrimônio do agressor"], "explicacao": "Antes, o art. 12-C falava em risco à vida ou à integridade física ou psicológica."}, {"id": 11574, "materia": "leg", "nivel": 3, "enunciado": "Segundo a Lei 15.412/2026, as medidas protetivas de natureza cível, como os alimentos provisórios fixados na Lei Maria da Penha:", "opcoes": ["Constituem título executivo judicial, sem necessidade de ação principal", "Dependem de nova ação de alimentos na vara de família para que possam ser cobradas judicialmente", "Só valem por 30 dias", "São títulos executivos extrajudiciais"], "explicacao": "Art. 22, § 10, da Lei 11.340/2006, incluído pela Lei 15.412/2026."}, {"id": 11575, "materia": "leg", "nivel": 1, "enunciado": "A Lei 15.409/2026 criou o Cadastro Nacional de Pessoas Condenadas por Violência contra a Mulher, que reúne:", "opcoes": ["Condenados por decisão definitiva por crimes como feminicídio, estupro e violência psicológica", "Todos os investigados em inquérito por crimes de violência doméstica, mesmo sem condenação definitiva", "Apenas as vítimas de violência doméstica", "Os agressores com medida protetiva, mesmo sem processo"], "explicacao": "O cadastro inclui só condenações transitadas em julgado, por um rol fechado de crimes."}, {"id": 11576, "materia": "leg", "nivel": 3, "enunciado": "A Lei 15.410/2026 (Lei Barbara Penna) passou a considerar falta grave, na Lei de Execução Penal, o preso em regime aberto, semiaberto ou em saída que:", "opcoes": ["Se aproxima da casa ou do trabalho da vítima, havendo medida protetiva", "Deixa de trabalhar por um dia", "Recebe visita fora do horário", "Recusa-se a participar das atividades educativas oferecidas pela unidade, sem justificativa"], "explicacao": "Art. 50, IX, da LEP, incluído pela Lei 15.410/2026."}, {"id": 11577, "materia": "leg", "nivel": 4, "enunciado": "A Lei 15.410/2026 incluiu na Lei de Tortura (art. 1º, III, da Lei 9.455/1997) a conduta de:", "opcoes": ["Submeter mulher, de forma reiterada, a intenso sofrimento físico ou mental no contexto de violência doméstica", "Ofender a honra da mulher em redes sociais, uma única vez, causando a ela intenso sofrimento mental e humilhação pública", "Descumprir medida protetiva sem violência", "Ameaçar a mulher por mensagem"], "explicacao": "A pena é de reclusão de 2 a 8 anos, com regime inicial fechado. Um ato isolado não se encaixa: exige reiteração."}, {"id": 11578, "materia": "leg", "nivel": 4, "enunciado": "Pela Lei 15.410/2026, o preso que ameaça ou agride a vítima durante o cumprimento da pena pode:", "opcoes": ["Ser incluído no Regime Disciplinar Diferenciado e transferido para outro estado ou presídio federal", "Ter a pena extinta", "Ser beneficiado com saída temporária, desde que se comprometa por escrito a não procurar mais a vítima nem seus parentes", "Receber indulto automático"], "explicacao": "Arts. 52, § 8º, e 86, § 4º, da LEP, incluídos pela Lei 15.410/2026."}, {"id": 11579, "materia": "pen", "nivel": 1, "enunciado": "A Lei 15.353/2026 deixou expresso no Código Penal que, no estupro de vulnerável contra menor de 14 anos, a vulnerabilidade da vítima é:", "opcoes": ["Absoluta, sem admitir prova em contrário", "Relativa, dependendo da experiência sexual da vítima", "Afastada se houver consentimento", "Afastada se houver relacionamento amoroso"], "explicacao": "A lei incorporou ao texto legal o entendimento da Súmula 593 do STJ."}, {"id": 11580, "materia": "pen", "nivel": 2, "enunciado": "No estupro de vulnerável contra menor de 14 anos, o consentimento da vítima, a experiência sexual anterior ou o relacionamento amoroso com o agente:", "opcoes": ["São irrelevantes para a configuração do crime", "Excluem o crime", "Reduzem a pena pela metade", "Transformam o crime em importunação sexual, de pena menor e sem natureza hedionda"], "explicacao": "Súmula 593 do STJ e Lei 15.353/2026."}, {"id": 11581, "materia": "leg", "nivel": 2, "enunciado": "Com a Lei 15.487/2026, a posse ou o armazenamento de material de abuso sexual infantil (art. 241-B do ECA) passou a ter pena de:", "opcoes": ["Reclusão de 3 a 6 anos e multa", "Reclusão de 1 a 4 anos e multa", "Detenção de 6 meses a 2 anos", "Reclusão de 4 a 10 anos e multa"], "explicacao": "A Lei 15.487/2026 elevou a pena do art. 241-B."}, {"id": 11582, "materia": "leg", "nivel": 3, "enunciado": "A Lei 15.487/2026 passou a punir, com a mesma pena do armazenamento (art. 241-B do ECA), quem:", "opcoes": ["Acessa ou assiste, por streaming, material de abuso sexual infantil com finalidade lasciva", "Denuncia o material às autoridades", "Apaga o material sem visualizar", "Recebe o material por aplicativo de mensagens sem saber do conteúdo e o apaga logo depois de perceber do que se trata"], "explicacao": "Novo § 4º do art. 241-B do ECA."}, {"id": 11583, "materia": "leg", "nivel": 4, "enunciado": "Pela Lei 15.487/2026, passaram a ser hediondos, entre outros, os crimes do ECA de:", "opcoes": ["Produzir, vender e divulgar material de abuso sexual infantil e aliciar criança pela internet", "Deixar de comunicar à autoridade competente os casos de maus-tratos de que tenha conhecimento, no caso de professor ou médico", "Vender bebida alcoólica a adolescente", "Hospedar criança em hotel sem autorização dos pais"], "explicacao": "Art. 1º, parágrafo único, VII, da Lei 8.072/1990: arts. 240, 241, 241-A, 241-B (caput), 241-D e 244-A do ECA. O art. 241-C (simulação) ficou de fora."}, {"id": 11584, "materia": "leg", "nivel": 2, "enunciado": "A pena do crime de produzir ou registrar cena de sexo explícito envolvendo criança ou adolescente (art. 240 do ECA), após a Lei 15.487/2026, é de:", "opcoes": ["Reclusão de 4 a 10 anos e multa", "Reclusão de 2 a 6 anos e multa", "Reclusão de 1 a 4 anos", "Detenção de 1 a 3 anos"], "explicacao": "Art. 240 do ECA, com a redação da Lei 15.487/2026."}, {"id": 11585, "materia": "pen", "nivel": 3, "enunciado": "Com a Lei 14.994/2024, a ameaça cometida contra a mulher por razões da condição do sexo feminino:", "opcoes": ["Tem a pena aplicada em dobro e é de ação penal pública incondicionada", "Depende de representação, como qualquer ameaça", "É de ação penal privada", "Tem a pena reduzida de 1/3 se não houver violência física e depende sempre de representação da vítima"], "explicacao": "Art. 147, §§ 1º e 2º, do CP. Fora dessa hipótese, a ameaça continua dependendo de representação."}, {"id": 11586, "materia": "pen", "nivel": 4, "enunciado": "Tiago ameaçou de morte a ex-namorada, por não aceitar o fim do relacionamento. Dias depois, ela quer desistir do processo. Pela lei atual:", "opcoes": ["Não pode, pois a ameaça contra a mulher por razões da condição do sexo feminino é de ação incondicionada", "Pode, em audiência perante o juiz, antes do recebimento da denúncia, por se tratar de crime de ameaça, que é condicionado", "Pode, na delegacia, até a conclusão do inquérito", "Pode, por se tratar de crime de ação privada"], "explicacao": "Art. 147, § 2º, do CP, com a redação da Lei 14.994/2024: somente se procede mediante representação, exceto na hipótese do § 1º (contra a mulher por razões da condição do sexo feminino)."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select nivel, count(*) as questoes_novas from public.questoes where id between 11547 and 11586 group by nivel order by nivel;
select public.questoes_versao() as nova_versao;
